mapper.update:
UPDATE m_housework
SET
    default_assignee_user_id = NULL
  , update_user_id = #{loginUserId}
  , update_program = #{program}
WHERE
    household_id = #{householdId}
  AND default_assignee_user_id = #{userId}

UPDATE m_housework
SET
    name = #{item.name}
  , description = #{item.description}
  , category = #{item.category}
  , recurrence_type = #{item.recurrenceType}
  , weekly_days = #{item.weeklyDays}
  , day_of_month = #{item.dayOfMonth}
  , nth_week = #{item.nthWeek}
  , weekday = #{item.weekday}
  , start_date = #{item.startDate}
  , end_date = #{item.endDate}
  , default_assignee_user_id = #{item.defaultAssigneeUserId}
  , update_user_id = #{userId}
  , update_program = #{program}
WHERE
    housework_id = #{item.houseworkId};
